('cmwhy3rdf0015tzjsghyu79pf', 'cctv-kit', 'پکیج دوربین مداربسته ۴ دوربین', '4-Camera CCTV Kit', 'ست کامل ۴ دوربین دام + NVR + هارد ۱ ترابایت + کابل و نصب؛ مناسب منزل، مغازه و شرکت با دید در شب و دسترسی موبایل.', 'Complete 4-dome camera kit + NVR + 1TB HDD + cabling and installation; ideal for homes, shops and offices with night vision and mobile access.', 16625000, 'cctv', '۱۸ ماه گارانتی', TRUE, 1, 'GOODS', 'سایر', NULL, NULL, 16625000, 'قیمت‌گذاری داخلی الو شتاب — نیاز به استعلام روز انبار', NULL, NULL, NULL, NULL, 'MANUAL', 'PENDING_REVIEW', '2026-11-17 12:45:27.231', 5, NULL, '2026-11-15 14:44:12.243', '2026-11-17 12:45:27.232'),
('cmwhy3rdg0016tzjspq33gicl', 'cctv-camera', 'دوربین مداربسته دام', 'Dome CCTV Camera', 'دوربین دام ۲ مگاپیکسل دید در شب، مقاوم در برابر نفوذ و شرایط سخت؛ مناسب فضای داخلی و خارجی.', '2MP dome camera with night vision, vandal-resistant and weatherproof; suitable for indoor and outdoor use.', 3724000, 'camera', '۱۲ ماه گارانتی', TRUE, 2, 'GOODS', 'سایر', NULL, NULL, 3724000, 'قیمت‌گذاری داخلی الو شتاب — نیاز به استعلام روز انبار', NULL, NULL, NULL, NULL, 'MANUAL', 'PENDING_REVIEW', '2026-11-17 12:45:27.235', 5, NULL, '2026-11-15 14:44:12.244', '2026-11-17 12:45:27.235'),
('cmwhy3rdh0017tzjsk6qzzwan', 'nvr', 'دستگاه NVR ضبط تصاویر', 'NVR Recorder', 'دستگاه ضبط ۴ و ۸ کاناله با پشتیبانی هارد تا ۸ ترابایت، خروجی HDMI و دسترسی از راه دور با موبایل.', '4/8-channel recorder supporting up to 8TB HDD, HDMI output and remote mobile access.', 9177000, 'harddrive', '۱۸ ماه گارانتی', TRUE, 3, 'GOODS', 'سایر', NULL, NULL, 9177000, 'قیمت‌گذاری داخلی الو شتاب — نیاز به استعلام روز انبار', NULL, NULL, NULL, NULL, 'MANUAL', 'PENDING_REVIEW', '2026-11-17 12:45:27.236', 5, NULL, '2026-11-15 14:44:12.245', '2026-11-17 12:45:27.237'),
('cmwhy3rdh0018tzjsbjwdn5eg', 'router', 'روتر بی‌سیم دوهزبند', 'Dual-Band Wi-Fi Router', 'روتر AC1200 دوهزبند با آنتن‌های پرقدرت، پوشش کامل منزل و دفتر، پورت گیگابیت و تنظیم آسان.', 'AC1200 dual-band router with high-gain antennas, full home/office coverage, gigabit ports and easy setup.', 4256000, 'router', '۱۲ ماه گارانتی', TRUE, 4, 'GOODS', 'سایر', NULL, NULL, 4256000, 'قیمت‌گذاری داخلی الو شتاب — نیاز به استعلام روز انبار', NULL, NULL, NULL, NULL, 'MANUAL', 'PENDING_REVIEW', '2026-11-17 12:45:27.238', 5, NULL, '2026-11-15 14:44:12.246', '2026-11-17 12:45:27.239'),
('cmwhy3rdi0019tzjswnij0vgh', 'switch', 'سوییچ شبکه ۸ پورت', '8-Port Network Switch', 'سوییچ ۸ پورت گیگابیت فلزی با پلاگ‌اند‌پلی؛ مناسب شبکه‌های خانگی و اداری با نصب روی دیوار.', '8-port gigabit metal switch, plug-and-play; ideal for home and office networks with wall mounting.', 2527000, 'cable', '۱۲ ماه گارانتی', TRUE, 5, 'GOODS', 'سایر', NULL, NULL, 2527000, 'قیمت‌گذاری داخلی الو شتاب — نیاز به استعلام روز انبار', NULL, NULL, NULL, NULL, 'MANUAL', 'PENDING_REVIEW', '2026-11-17 12:45:27.240', 5, NULL, '2026-11-15 14:44:12.247', '2026-11-17 12:45:27.240'),
('cmwhy3rdk001atzjsbi8vxzhr', 'laptop', 'لپ‌تاپ اداری و دانشجویی', 'Office & Student Laptop', 'لپ‌تاپ اقتصادی با پردازندهٔ نسل جدید، رم ۱۶ گیگ، SSD ۵۱۲، نمایشگر فول‌اچ‌دی و وزن سبک — مناسب کار روزمره و درس.', 'Budget laptop with latest-gen CPU, 16GB RAM, 512GB SSD, Full-HD display and light weight — great for daily work and study.', 28000000, 'laptop', '۲۴ ماه گارانتی', FALSE, 6, 'GOODS', 'سایر', NULL, NULL, 0, 'قیمت‌گذاری داخلی الو شتاب — نیاز به استعلام روز انبار', NULL, NULL, NULL, NULL, 'MANUAL', 'ACTIVE', NULL, 5, NULL, '2026-11-15 14:44:12.248', '2026-11-17 12:02:04.550'),
('cmwhy3rdk001btzjsseu2d6ks', 'desktop', 'کامپیوتر اداری آماده', 'Ready Office Desktop', 'کیس کامل اداری با پردازندهٔCore i5، رم ۱۶ گیگ، SSD ۵۱۲ و مانیتور ۲۲ اینچ؛ نصب و راه‌اندازی رایگان در محل.', 'Complete office PC with Core i5, 16GB RAM, 512GB SSD and a 22-inch monitor; free on-site setup.', 22000000, 'monitor', '۲۴ ماه گارانتی', FALSE, 7, 'GOODS', 'سایر', NULL, NULL, 0, 'قیمت‌گذاری داخلی الو شتاب — نیاز به استعلام روز انبار', NULL, NULL, NULL, NULL, 'MANUAL', 'ACTIVE', NULL, 5, NULL, '2026-11-15 14:44:12.249', '2026-11-17 12:02:04.552'),
('cmwhy3rdl001ctzjseqn0s7lx', 'printer', 'پرینتر لیزری', 'Laser Printer', 'پرینتر لیزری سیاه‌وسفید شبکه‌ای و وای‌فای، چاپ دوطرفهٔ خودکار؛ مناسب دفتر و منزل با کارتریج اقتصادی.', 'Network & Wi-Fi mono laser printer with automatic duplex; ideal for office and home with economical toner.', 7500000, 'printer', '۱۲ ماه گارانتی', FALSE, 8, 'GOODS', 'سایر', NULL, NULL, 0, 'قیمت‌گذاری داخلی الو شتاب — نیاز به استعلام روز انبار', NULL, NULL, NULL, NULL, 'MANUAL', 'ACTIVE', NULL, 5, NULL, '2026-11-15 14:44:12.250', '2026-11-17 12:02:04.554'),
